#if defined(__WINDOWS__)
// simple emulation of the hardware switch mask for Windows builds
static volatile int _win_switch_mask = 0;

InputState currentState;

int get_sw() {
	return _win_switch_mask & 0xFF;
}

void set_win_switch_mask(int mask) {
	_win_switch_mask = mask & 0xFF;
}

void press_win_button(void) {
	// nothing stored here; main will call confirmSelectedSquare() directly
}

// FUNCTION GENERATED BY CHATGPT. Only used for testing on windows, not included in final dtek binary.
int poll() {
	SDL_Event event;
	while(SDL_PollEvent(&event)) {
		if (event.type == SDL_EVENT_QUIT) return 1;
		if (event.type == SDL_EVENT_KEY_DOWN) {
			SDL_KeyboardEvent *ke = &event.key;

			SDL_Scancode sc = ke->scancode;
			SDL_Keycode key = ke->key;

			int num = -1;

			if (key >= '1' && key <= '9') {
				num = key - '1';
			}

			if (num >= 0 && num <= 8) {
				print_dec(num);
				print("\n");
				_win_switch_mask ^= (1 << num);
				setSelectedSquare(_win_switch_mask & 0x3F);
			}

			if (key == 'b' || key == 'B') {
				currentState.pressedButton = 1;
				confirmSelectedSquare();
			}
		}
	}
	return 0;
}

InputState getInputState() {
	InputState curr = currentState;
	currentState = (InputState){
		.switches = get_sw(),
		.pressedButton = 0
	};
	return curr;
}
#endif